CREATE TRIGGER IF NOT EXISTS document_failure_contribution_delete AFTER DELETE ON document_failure_contributions
      BEGIN INSERT INTO document_failure_totals(project_id,failure,transcripts,latest_at,diagnostic,visible)
  SELECT OLD.project_id,OLD.failure,-1,OLD.updated_at,OLD.diagnostic,
    EXISTS(SELECT 1 FROM projects WHERE project_id=OLD.project_id AND archived_at IS NULL)
  ON CONFLICT(project_id,failure) DO UPDATE SET transcripts=transcripts+excluded.transcripts;
  UPDATE document_failure_totals SET (latest_at,diagnostic)=(SELECT updated_at,diagnostic FROM (SELECT updated_at,diagnostic FROM document_failure_contributions
  WHERE (project_id,failure)=(OLD.project_id,OLD.failure) ORDER BY updated_at DESC,transcript_id DESC,generation DESC LIMIT 1))
    WHERE (project_id,failure)=(OLD.project_id,OLD.failure);
  DELETE FROM document_failure_totals WHERE (project_id,failure)=(OLD.project_id,OLD.failure) AND transcripts=0; END;

CREATE TRIGGER IF NOT EXISTS document_failure_total_delete AFTER DELETE ON document_failure_totals
      BEGIN INSERT INTO document_failure_head(slot,transcripts) VALUES(1,-OLD.visible*OLD.transcripts)
        ON CONFLICT(slot) DO UPDATE SET transcripts=transcripts+excluded.transcripts;
        UPDATE document_failure_head SET (latest_at,failure)=(SELECT latest_at,failure FROM (SELECT latest_at,failure FROM document_failure_totals WHERE visible=1 AND transcripts>0 ORDER BY latest_at DESC,project_id DESC,failure DESC LIMIT 1)) WHERE slot=1; END;

