CREATE TRIGGER IF NOT EXISTS document_failure_project_insert AFTER INSERT ON projects
      BEGIN UPDATE document_failure_totals SET visible=NEW.archived_at IS NULL WHERE project_id=NEW.project_id; END;

CREATE TRIGGER IF NOT EXISTS document_failure_project_update AFTER UPDATE OF archived_at ON projects
      BEGIN UPDATE document_failure_totals SET visible=NEW.archived_at IS NULL WHERE project_id=NEW.project_id; END;

